def is_majority(arr, n, x):
    if n <= 0:
        return False

    def lower_bound(target):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] < target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    def upper_bound(target):
        lo, hi = 0, n
        while lo < hi:
            mid = (lo + hi) // 2
            if arr[mid] <= target:
                lo = mid + 1
            else:
                hi = mid
        return lo

    first = lower_bound(x)
    if first == n or arr[first] != x:
        return False

    last = upper_bound(x)
    return (last - first) * 2 > n


assert is_majority([1, 2, 3, 3, 3, 3, 10], 7, 3) == True
```

